<?php
declare(strict_types=1);require __DIR__.'/inc/db.php';require __DIR__.'/inc/page.php';require __DIR__.'/inc/otp_service.php';$errors=[];
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){require_post_csrf();$name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$phone=normalize_ph_phone((string)($_POST['phone']??''));$password=(string)($_POST['password']??'');
 if(strlen($name)<2)$errors[]='Enter your full name.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email address.';if(!$phone)$errors[]='Enter a valid Philippine mobile number.';if(strlen($password)<8)$errors[]='Password must be at least 8 characters.';if($password!==($_POST['password_confirmation']??''))$errors[]='Passwords do not match.';
 if(!$errors){try{$pdo->beginTransaction();$q=$pdo->prepare('INSERT INTO users(name,email,phone,password_hash,role,is_active) VALUES(?,?,?,?,\'customer\',0)');$q->execute([$name,$email,$phone,password_hash($password,PASSWORD_DEFAULT)]);$uid=(int)$pdo->lastInsertId();$otp=issue_otp($pdo,$uid,'registration',$phone,$email);$pdo->commit();$_SESSION['otp_challenge_id']=$otp['challenge_id'];$feedback=otp_delivery_feedback($otp);$_SESSION['otp_notice']=$feedback['message'];$_SESSION['otp_notice_type']=$feedback['type'];redirect('/AI-CAKE/verify_otp.php');}catch(PDOException $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$e->getCode()==='23000'?'That email address or mobile number is already registered.':'Registration could not be completed.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$e->getMessage();}}}
page_start('Register');?><main class="auth-shell"><section class="app-card auth-card p-4 p-md-5"><div class="eyebrow mb-2">Customer registration</div><h1 class="h3 fw-bold">Create your account</h1><p class="help-text">We will verify your Philippine mobile number before activation.</p><?php foreach($errors as $error):?><div class="alert alert-danger" role="alert"><?=e($error)?></div><?php endforeach;?><form method="post"><?=csrf_field()?><div class="mb-3"><label for="name" class="form-label">Full name</label><input id="name" name="name" autocomplete="name" required class="form-control" value="<?=e($_POST['name']??'')?>"></div><div class="mb-3"><label for="email" class="form-label">Email address</label><input id="email" name="email" type="email" autocomplete="email" required class="form-control" value="<?=e($_POST['email']??'')?>"></div><div class="mb-3"><label for="phone" class="form-label">Mobile number</label><input id="phone" name="phone" inputmode="tel" placeholder="09XXXXXXXXX" required class="form-control" value="<?=e($_POST['phone']??'')?>"></div><div class="row g-3"><div class="col-md-6"><label for="password" class="form-label">Password</label><input id="password" name="password" type="password" minlength="8" autocomplete="new-password" required class="form-control"></div><div class="col-md-6"><label for="password_confirmation" class="form-label">Confirm password</label><input id="password_confirmation" name="password_confirmation" type="password" minlength="8" autocomplete="new-password" required class="form-control"></div></div><button class="btn btn-purple w-100 mt-4">Create account</button></form><p class="text-center mt-4 mb-0">Already registered? <a href="login.php">Log in</a></p></section></main><?php page_end();
